 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_viewOtherForm (인자 미해석) · document.getElementById('${doc.acptNo}'+'_0_otherForm').style.display = 'none'; (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}' , '${doc.beforeFormVer}' , '${doc.beforeEngFormVer}', '${doc.oldFormVerUseYn}' , '${doc.langTpCd}'  ,'${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.addOrgnDisclsAcptNo}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.sndlocTpCd}','${doc.exmptObjDisclsYn}', '${doc.disclsAcptTpCd}','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${doc.disclsObjIsuCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }', '${doc.editClssCd }', '${doc.engMandatory1Yn}'); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}' , '${doc.currFormVer}' , '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}' , '${doc.langTpCd}'  ,'${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.addOrgnDisclsAcptNo}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.sndlocTpCd}','${doc.exmptObjDisclsYn}', '${doc.disclsAcptTpCd}','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${doc.disclsObjIsuCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }', '${doc.editClssCd }', '${doc.engMandatory1Yn}'); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}' , '${doc.currFormVer}' , '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}' , '${doc.langTpCd}'  ,'${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.addOrgnDisclsAcptNo}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.sndlocTpCd}','${doc.exmptObjDisclsYn}', '${doc.disclsAcptTpCd}','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${doc.disclsObjIsuCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }', '${doc.editClssCd }', '${doc.engMandatory1Yn}'); (EL 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

/**
 * @method
