};

/**
 * @method
 * @name grd_docPageList_fmt_formKorNm
 * @description grd doc Page List fmt form Kor Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_formKorNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "oldFormVerUseYn") ?? '') : '');
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? '') + '</a>'; }
        return '<a href="javascript:void(0)"' + (true ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? '') + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.formKorNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column5
 * @description grd doc Page List fmt column5 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column5 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'F') { return "최초"; }
        if (v === 'M') { return "정정"; }
        if (v === 'A') { return "첨부추가"; }
        if (v === 'U') { return "첨부정정"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column5" }); return String(data ?? ''); }
};

